recipes.code:
{
  "inputs": [
    {
      "id": "portlandmaps-api-key",
      "type": "promptString",
      "description": "PortlandMaps API key. Required for the /api/* tools; without it those endpoints return error payloads.",
      "password": true
    }
  ],
  "servers": {
    "portlandmaps": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "portlandmaps-mcp@0.2.5"
      ],
      "env": {
        "PORTLANDMAPS_API_KEY": "${input:portlandmaps-api-key}",
        "PORTLANDMAPS_API_KEY_PARAM": "<portlandmaps-api-key-param>",
        "PORTLANDMAPS_CACHE_TTL_MS": "<portlandmaps-cache-ttl-ms>"
      }
    }
  }
}
